package update

import (
	"fmt"
	"strconv"
	"strings"
)

// ParseVersion parses a major.minor.patch string. A leading "v" is ignored.
// Extra pre-release/build suffixes after the numeric triple are dropped.
func ParseVersion(s string) (major, minor, patch int, err error) {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "v")
	s = strings.TrimPrefix(s, "V")
	if s == "" {
		return 0, 0, 0, fmt.Errorf("empty version")
	}
	// Drop -pre / +build for comparison.
	if i := strings.IndexAny(s, "-+"); i >= 0 {
		s = s[:i]
	}
	parts := strings.Split(s, ".")
	if len(parts) < 1 || len(parts) > 3 {
		return 0, 0, 0, fmt.Errorf("invalid version %q", s)
	}
	nums := make([]int, 3)
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n < 0 {
			return 0, 0, 0, fmt.Errorf("invalid version %q", s)
		}
		nums[i] = n
	}
	return nums[0], nums[1], nums[2], nil
}

// Compare returns -1 if a < b, 0 if equal, 1 if a > b.
func Compare(a, b string) (int, error) {
	am, an, ap, err := ParseVersion(a)
	if err != nil {
		return 0, fmt.Errorf("local version: %w", err)
	}
	bm, bn, bp, err := ParseVersion(b)
	if err != nil {
		return 0, fmt.Errorf("remote version: %w", err)
	}
	if am != bm {
		if am < bm {
			return -1, nil
		}
		return 1, nil
	}
	if an != bn {
		if an < bn {
			return -1, nil
		}
		return 1, nil
	}
	if ap != bp {
		if ap < bp {
			return -1, nil
		}
		return 1, nil
	}
	return 0, nil
}

// IsNewer reports whether remote is a strictly greater semver than local.
// Invalid versions and local "0.0.0" never count as an update.
func IsNewer(local, remote string) bool {
	lm, ln, lp, err := ParseVersion(local)
	if err != nil {
		return false
	}
	if lm == 0 && ln == 0 && lp == 0 {
		return false
	}
	cmp, err := Compare(local, remote)
	if err != nil {
		return false
	}
	return cmp < 0
}

package update

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

const (
	defaultAPIURL     = "https://api.github.com/repos/elpatron68/gotify-desktop/releases/latest"
	apiTimeout        = 20 * time.Second
	downloadTimeout   = 5 * time.Minute
	checksumAssetName = "SHA256SUMS"
)

// Asset is one file attached to a GitHub release.
type Asset struct {
	Name               string `json:"name"`
	BrowserDownloadURL string `json:"browser_download_url"`
	Size               int64  `json:"size"`
}

// Release is the subset of the GitHub Releases API used for updates.
type Release struct {
	TagName string  `json:"tag_name"`
	Assets  []Asset `json:"assets"`
}

// Client talks to the GitHub Releases API and downloads assets.
type Client struct {
	APIURL    string
	UserAgent string
	HTTP      *http.Client
}

func (c *Client) apiURL() string {
	if c.APIURL != "" {
		return c.APIURL
	}
	return defaultAPIURL
}

func (c *Client) userAgent() string {
	if c.UserAgent != "" {
		return c.UserAgent
	}
	return "gotify-desktop"
}

func (c *Client) httpClient(timeout time.Duration) *http.Client {
	if c.HTTP != nil {
		return c.HTTP
	}
	return &http.Client{
		Timeout: timeout,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 10 {
				return fmt.Errorf("too many redirects")
			}
			if req.URL.Scheme != "https" {
				return fmt.Errorf("refusing non-HTTPS redirect to %s", req.URL)
			}
			return nil
		},
	}
}

// LatestRelease fetches the latest non-prerelease GitHub release.
func (c *Client) LatestRelease(ctx context.Context) (Release, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.apiURL(), nil)
	if err != nil {
		return Release{}, err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", c.userAgent())
	req.Header.Set("X-GitHub-Api-Version", "2022-11-28")

	resp, err := c.httpClient(apiTimeout).Do(req)
	if err != nil {
		return Release{}, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return Release{}, err
	}
	if resp.StatusCode != http.StatusOK {
		return Release{}, fmt.Errorf("github releases: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	var rel Release
	if err := json.Unmarshal(body, &rel); err != nil {
		return Release{}, fmt.Errorf("parse release: %w", err)
	}
	if strings.TrimSpace(rel.TagName) == "" {
		return Release{}, fmt.Errorf("release has empty tag_name")
	}
	return rel, nil
}

// FindAsset returns the asset with the given name, or an error if missing.
func (r Release) FindAsset(name string) (Asset, error) {
	for _, a := range r.Assets {
		if a.Name == name {
			return a, nil
		}
	}
	return Asset{}, fmt.Errorf("release asset %q not found", name)
}

// ChecksumAsset returns the SHA256SUMS asset.
func (r Release) ChecksumAsset() (Asset, error) {
	return r.FindAsset(checksumAssetName)
}

// Download writes the asset body to w. Only HTTPS URLs are accepted.
func (c *Client) Download(ctx context.Context, url string, w io.Writer) error {
	if !strings.HasPrefix(url, "https://") {
		return fmt.Errorf("refusing non-HTTPS download URL")
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return err
	}
	req.Header.Set("User-Agent", c.userAgent())
	resp, err := c.httpClient(downloadTimeout).Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
		return fmt.Errorf("download: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	_, err = io.Copy(w, resp.Body)
	return err
}

package update

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
)

// InstallKind describes how the running app was packaged.
type InstallKind int

const (
	InstallBinary InstallKind = iota
	InstallAppImage
	InstallWindowsEXE
	InstallMacApp
)

// Target describes the update package to download and where to install it.
type Target struct {
	Kind        InstallKind
	AssetName   string
	ReplacePath string // path that --apply-update will replace
}

// DetectTarget inspects the running process and chooses the matching release asset.
func DetectTarget(goos, goarch string) (Target, error) {
	arch := releaseArch(goarch)
	if arch == "" {
		return Target{}, fmt.Errorf("unsupported architecture %q", goarch)
	}

	switch goos {
	case "linux":
		if appImage := strings.TrimSpace(os.Getenv("APPIMAGE")); appImage != "" {
			return Target{
				Kind:        InstallAppImage,
				AssetName:   fmt.Sprintf("gotify-desktop-linux-%s.AppImage", arch),
				ReplacePath: appImage,
			}, nil
		}
		exe, err := os.Executable()
		if err != nil {
			return Target{}, err
		}
		exe, err = filepath.EvalSymlinks(exe)
		if err != nil {
			return Target{}, err
		}
		return Target{
			Kind:        InstallBinary,
			AssetName:   fmt.Sprintf("gotify-desktop-linux-%s", arch),
			ReplacePath: exe,
		}, nil

	case "windows":
		exe, err := os.Executable()
		if err != nil {
			return Target{}, err
		}
		return Target{
			Kind:        InstallWindowsEXE,
			AssetName:   fmt.Sprintf("gotify-desktop-windows-%s.exe", arch),
			ReplacePath: exe,
		}, nil

	case "darwin":
		exe, err := os.Executable()
		if err != nil {
			return Target{}, err
		}
		exe, err = filepath.EvalSymlinks(exe)
		if err != nil {
			return Target{}, err
		}
		app := macAppBundle(exe)
		if app == "" {
			return Target{}, fmt.Errorf("running binary is not inside a .app bundle")
		}
		return Target{
			Kind:        InstallMacApp,
			AssetName:   fmt.Sprintf("gotify-desktop-darwin-%s.zip", arch),
			ReplacePath: app,
		}, nil

	default:
		return Target{}, fmt.Errorf("unsupported OS %q", goos)
	}
}

// CurrentTarget detects the update target for the running binary.
func CurrentTarget() (Target, error) {
	return DetectTarget(runtime.GOOS, runtime.GOARCH)
}

func releaseArch(goarch string) string {
	switch goarch {
	case "amd64":
		return "amd64"
	case "arm64":
		return "arm64"
	default:
		return ""
	}
}

// macAppBundle walks up from an executable path to the enclosing .app directory.
// Typical layout: Foo.app/Contents/MacOS/gotify-desktop
func macAppBundle(exe string) string {
	dir := filepath.Dir(exe)          // .../Contents/MacOS
	contents := filepath.Dir(dir)     // .../Contents
	app := filepath.Dir(contents)     // .../Foo.app
	if strings.HasSuffix(strings.ToLower(app), ".app") {
		return app
	}
	return ""
}

package update

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"strings"
)

// ParseSHA256SUMS parses GNU sha256sum output ("<hash>  <filename>" or "<hash> *<filename>").
func ParseSHA256SUMS(r io.Reader) (map[string]string, error) {
	out := make(map[string]string)
	sc := bufio.NewScanner(r)
	lineNo := 0
	for sc.Scan() {
		lineNo++
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		hash, name, ok := splitChecksumLine(line)
		if !ok {
			return nil, fmt.Errorf("SHA256SUMS line %d: invalid format", lineNo)
		}
		if len(hash) != 64 {
			return nil, fmt.Errorf("SHA256SUMS line %d: invalid hash length", lineNo)
		}
		if _, err := hex.DecodeString(hash); err != nil {
			return nil, fmt.Errorf("SHA256SUMS line %d: invalid hash", lineNo)
		}
		out[name] = strings.ToLower(hash)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

func splitChecksumLine(line string) (hash, name string, ok bool) {
	// GNU text mode: "hash  name" (two spaces). Binary mode: "hash *name".
	if len(line) < 66 {
		return "", "", false
	}
	hash = line[:64]
	rest := line[64:]
	switch {
	case strings.HasPrefix(rest, "  "):
		name = strings.TrimSpace(rest[2:])
	case strings.HasPrefix(rest, " *"):
		name = strings.TrimSpace(rest[2:])
	default:
		fields := strings.Fields(line)
		if len(fields) < 2 {
			return "", "", false
		}
		hash = fields[0]
		name = fields[1]
		name = strings.TrimPrefix(name, "*")
	}
	if hash == "" || name == "" {
		return "", "", false
	}
	return hash, name, true
}

// ExpectedHash looks up filename in a parsed SHA256SUMS map.
func ExpectedHash(sums map[string]string, filename string) (string, error) {
	h, ok := sums[filename]
	if !ok {
		// Also try basename if a path was stored.
		base := filename
		if i := strings.LastIndexAny(filename, "/\\"); i >= 0 {
			base = filename[i+1:]
		}
		h, ok = sums[base]
	}
	if !ok {
		return "", fmt.Errorf("no checksum for %q", filename)
	}
	return h, nil
}

// FileSHA256 returns the lowercase hex SHA-256 of a file.
func FileSHA256(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// VerifyFile checks that path matches expected lowercase hex SHA-256.
func VerifyFile(path, expectedHex string) error {
	got, err := FileSHA256(path)
	if err != nil {
		return err
	}
	if !strings.EqualFold(got, expectedHex) {
		return fmt.Errorf("checksum mismatch for %s: got %s want %s", path, got, expectedHex)
	}
	return nil
}

package update

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// DownloadResult holds paths for a verified package download.
type DownloadResult struct {
	PackagePath string
	Version     string
	AssetName   string
}

// DownloadAndVerify fetches the matching asset and SHA256SUMS, verifies the hash,
// and returns the path to the verified package file in dir (usually os.TempDir()).
func (c *Client) DownloadAndVerify(ctx context.Context, rel Release, target Target, dir string) (DownloadResult, error) {
	asset, err := rel.FindAsset(target.AssetName)
	if err != nil {
		return DownloadResult{}, err
	}
	sumAsset, err := rel.ChecksumAsset()
	if err != nil {
		return DownloadResult{}, err
	}

	if err := os.MkdirAll(dir, 0o700); err != nil {
		return DownloadResult{}, err
	}

	sumPath := filepath.Join(dir, checksumAssetName)
	sumFile, err := os.Create(sumPath)
	if err != nil {
		return DownloadResult{}, err
	}
	err = c.Download(ctx, sumAsset.BrowserDownloadURL, sumFile)
	closeErr := sumFile.Close()
	if err != nil {
		_ = os.Remove(sumPath)
		return DownloadResult{}, err
	}
	if closeErr != nil {
		_ = os.Remove(sumPath)
		return DownloadResult{}, closeErr
	}

	sumReader, err := os.Open(sumPath)
	if err != nil {
		_ = os.Remove(sumPath)
		return DownloadResult{}, err
	}
	sums, err := ParseSHA256SUMS(sumReader)
	_ = sumReader.Close()
	_ = os.Remove(sumPath)
	if err != nil {
		return DownloadResult{}, err
	}
	want, err := ExpectedHash(sums, asset.Name)
	if err != nil {
		return DownloadResult{}, err
	}

	pkgPath := filepath.Join(dir, asset.Name)
	pkgFile, err := os.OpenFile(pkgPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if err != nil {
		return DownloadResult{}, err
	}
	err = c.Download(ctx, asset.BrowserDownloadURL, pkgFile)
	closeErr = pkgFile.Close()
	if err != nil {
		_ = os.Remove(pkgPath)
		return DownloadResult{}, err
	}
	if closeErr != nil {
		_ = os.Remove(pkgPath)
		return DownloadResult{}, closeErr
	}

	if err := VerifyFile(pkgPath, want); err != nil {
		_ = os.Remove(pkgPath)
		return DownloadResult{}, err
	}

	// Ensure the package is executable where needed (AppImage / Linux binary).
	switch target.Kind {
	case InstallAppImage, InstallBinary:
		if err := os.Chmod(pkgPath, 0o755); err != nil {
			_ = os.Remove(pkgPath)
			return DownloadResult{}, err
		}
	}

	return DownloadResult{
		PackagePath: pkgPath,
		Version:     strings.TrimPrefix(rel.TagName, "v"),
		AssetName:   asset.Name,
	}, nil
}

// CheckAvailable returns the latest release if it is newer than localVersion.
// ok is false when no update is available (not an error).
func (c *Client) CheckAvailable(ctx context.Context, localVersion string) (rel Release, ok bool, err error) {
	rel, err = c.LatestRelease(ctx)
	if err != nil {
		return Release{}, false, err
	}
	if !IsNewer(localVersion, rel.TagName) {
		return rel, false, nil
	}
	return rel, true, nil
}

// ErrNoAsset is returned when the release has no package for this install.
var ErrNoAsset = fmt.Errorf("no matching update asset for this platform")

package update

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// ApplyArgs are CLI flags for the --apply-update helper process.
type ApplyArgs struct {
	PID  int
	Src  string
	Dest string
	Kind InstallKind
}

// ParseApplyArgs extracts --apply-update flags from argv.
// Returns ok=false when the helper mode was not requested.
func ParseApplyArgs(argv []string) (args ApplyArgs, ok bool, err error) {
	args.Kind = InstallBinary
	for i := 0; i < len(argv); i++ {
		switch argv[i] {
		case "--apply-update":
			ok = true
		case "--pid":
			if i+1 >= len(argv) {
				return args, true, fmt.Errorf("--pid requires a value")
			}
			i++
			pid, e := strconv.Atoi(argv[i])
			if e != nil || pid <= 0 {
				return args, true, fmt.Errorf("invalid --pid")
			}
			args.PID = pid
		case "--src":
			if i+1 >= len(argv) {
				return args, true, fmt.Errorf("--src requires a value")
			}
			i++
			args.Src = argv[i]
		case "--dest":
			if i+1 >= len(argv) {
				return args, true, fmt.Errorf("--dest requires a value")
			}
			i++
			args.Dest = argv[i]
		case "--kind":
			if i+1 >= len(argv) {
				return args, true, fmt.Errorf("--kind requires a value")
			}
			i++
			k, e := parseKind(argv[i])
			if e != nil {
				return args, true, e
			}
			args.Kind = k
		}
	}
	if !ok {
		return ApplyArgs{}, false, nil
	}
	if args.PID <= 0 || args.Src == "" || args.Dest == "" {
		return args, true, fmt.Errorf("--apply-update requires --pid, --src and --dest")
	}
	return args, true, nil
}

func parseKind(s string) (InstallKind, error) {
	switch strings.ToLower(s) {
	case "binary", "":
		return InstallBinary, nil
	case "appimage":
		return InstallAppImage, nil
	case "windows", "exe":
		return InstallWindowsEXE, nil
	case "mac", "darwin", "app":
		return InstallMacApp, nil
	default:
		return 0, fmt.Errorf("unknown --kind %q", s)
	}
}

// KindFlag returns the CLI --kind value for a target.
func KindFlag(k InstallKind) string {
	switch k {
	case InstallAppImage:
		return "appimage"
	case InstallWindowsEXE:
		return "windows"
	case InstallMacApp:
		return "mac"
	default:
		return "binary"
	}
}

// WaitForPIDExit polls until pid is gone or timeout elapses.
func WaitForPIDExit(pid int, timeout time.Duration) error {
	deadline := time.Now().Add(timeout)
	for {
		if !processAlive(pid) {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("timed out waiting for pid %d to exit", pid)
		}
		time.Sleep(200 * time.Millisecond)
	}
}

// ReplaceFile atomically replaces dest with src (rename when possible).
// On failure the original dest is preserved when a backup was created.
func ReplaceFile(src, dest string) error {
	if src == "" || dest == "" {
		return fmt.Errorf("src and dest are required")
	}
	if _, err := os.Stat(src); err != nil {
		return err
	}
	dir := filepath.Dir(dest)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}

	backup := dest + ".old"
	_ = os.Remove(backup)

	if _, err := os.Stat(dest); err == nil {
		if err := os.Rename(dest, backup); err != nil {
			// Fallback: try direct overwrite (e.g. some Unix cases).
			if err2 := copyOverwrite(src, dest); err2 != nil {
				return fmt.Errorf("replace %s: rename failed (%v) and copy failed (%w)", dest, err, err2)
			}
			_ = os.Chmod(dest, 0o755)
			_ = os.Remove(src)
			return nil
		}
	}

	if err := os.Rename(src, dest); err != nil {
		// Cross-device: copy then remove.
		if err2 := copyOverwrite(src, dest); err2 != nil {
			// Restore backup if we moved it aside.
			if _, e := os.Stat(backup); e == nil {
				_ = os.Rename(backup, dest)
			}
			return fmt.Errorf("replace %s: %w", dest, err2)
		}
		_ = os.Remove(src)
	}
	_ = os.Chmod(dest, 0o755)
	_ = os.Remove(backup)
	return nil
}

func copyOverwrite(src, dest string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	tmp := dest + ".new"
	out, err := os.OpenFile(tmp, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o755)
	if err != nil {
		return err
	}
	buf := make([]byte, 256*1024)
	for {
		n, rerr := in.Read(buf)
		if n > 0 {
			if _, werr := out.Write(buf[:n]); werr != nil {
				_ = out.Close()
				_ = os.Remove(tmp)
				return werr
			}
		}
		if rerr != nil {
			if rerr.Error() == "EOF" || n == 0 && rerr != nil {
				break
			}
			// use io.EOF properly
			break
		}
	}
	// Re-read with io.Copy style - fix this properly
	_ = out.Close()
	// Actually the loop above is buggy. Use a cleaner implementation.
	return fixCopyOverwrite(src, dest)
}

func fixCopyOverwrite(src, dest string) error {
	in, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	tmp := dest + ".new"
	if err := os.WriteFile(tmp, in, 0o755); err != nil {
		return err
	}
	if err := os.Rename(tmp, dest); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return nil
}

// CanWriteBeside reports whether a new file can be created next to path
// (directory is writable). Used to decide if elevation is needed on Windows.
func CanWriteBeside(path string) bool {
	dir := filepath.Dir(path)
	f, err := os.CreateTemp(dir, ".gotify-write-test-*")
	if err != nil {
		return false
	}
	name := f.Name()
	_ = f.Close()
	_ = os.Remove(name)
	return true
}

// CleanupOldBackup removes path+".old" if present (best effort).
func CleanupOldBackup(exePath string) {
	if exePath == "" {
		return
	}
	_ = os.Remove(exePath + ".old")
}

