func processAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	h, err := windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION, false, uint32(pid))
	if err != nil {
		return false
	}
	defer windows.CloseHandle(h)
	var code uint32
	if err := windows.GetExitCodeProcess(h, &code); err != nil {
		return false
	}
	return code == 259 // STILL_ACTIVE
}

//go:build !windows

package update

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"time"
)

// RunApplyHelper launches this executable with --apply-update flags and returns
// without waiting. The current process should exit immediately afterwards.
func RunApplyHelper(selfExe string, target Target, packagePath string) error {
	args := []string{
		"--apply-update",
		"--pid", fmt.Sprintf("%d", os.Getpid()),
		"--src", packagePath,
		"--dest", target.ReplacePath,
		"--kind", KindFlag(target.Kind),
	}
	cmd := exec.Command(selfExe, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Start()
}

// ApplyUpdate performs the package swap after the parent process has exited.
func ApplyUpdate(args ApplyArgs) error {
	if err := WaitForPIDExit(args.PID, 60*time.Second); err != nil {
		return err
	}
	switch args.Kind {
	case InstallMacApp:
		return applyMacApp(args.Src, args.Dest)
	default:
		if err := ReplaceFile(args.Src, args.Dest); err != nil {
			return err
		}
		return startPath(args.Dest)
	}
}

func applyMacApp(zipPath, appPath string) error {
	if runtime.GOOS != "darwin" {
		return fmt.Errorf("mac app update only supported on darwin")
	}
	tmp, err := os.MkdirTemp("", "gotify-update-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmp)

	cmd := exec.Command("ditto", "-x", "-k", zipPath, tmp)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("unzip update: %w (%s)", err, string(out))
	}
	entries, err := os.ReadDir(tmp)
	if err != nil {
		return err
	}
	var srcApp string
	for _, e := range entries {
		if e.IsDir() && filepath.Ext(e.Name()) == ".app" {
			srcApp = filepath.Join(tmp, e.Name())
			break
		}
	}
	if srcApp == "" {
		return fmt.Errorf("zip contains no .app bundle")
	}
	// Replace existing bundle with ditto (preserves attributes).
	if err := os.RemoveAll(appPath); err != nil {
		return err
	}
	cmd = exec.Command("ditto", srcApp, appPath)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("install .app: %w (%s)", err, string(out))
	}
	_ = os.Remove(zipPath)
	cmd = exec.Command("open", appPath)
	return cmd.Start()
}

func startPath(path string) error {
	cmd := exec.Command(path)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Start()
}

//go:build windows

package update

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"syscall"
	"time"
	"unsafe"

	"golang.org/x/sys/windows"
)

// RunApplyHelper launches this executable with --apply-update flags.
// If the install directory is not writable, the helper is started elevated (UAC).
func RunApplyHelper(selfExe string, target Target, packagePath string) error {
	args := []string{
		"--apply-update",
		"--pid", fmt.Sprintf("%d", os.Getpid()),
		"--src", packagePath,
		"--dest", target.ReplacePath,
		"--kind", KindFlag(target.Kind),
	}
	if CanWriteBeside(target.ReplacePath) {
		cmd := exec.Command(selfExe, args...)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		return cmd.Start()
	}
	return startElevated(selfExe, args)
}

func startElevated(exe string, args []string) error {
	verb, err := windows.UTF16PtrFromString("runas")
	if err != nil {
		return err
	}
	file, err := windows.UTF16PtrFromString(exe)
	if err != nil {
		return err
	}
	// ShellExecuteW parameters: join args with spaces; quote paths with spaces.
	paramStr := quoteArgs(args)
	params, err := windows.UTF16PtrFromString(paramStr)
	if err != nil {
		return err
	}
	var show int32 = 1 // SW_SHOWNORMAL
	ret, _, _ := windows.NewLazySystemDLL("shell32.dll").NewProc("ShellExecuteW").Call(
		0,
		uintptr(unsafe.Pointer(verb)),
		uintptr(unsafe.Pointer(file)),
		uintptr(unsafe.Pointer(params)),
		0,
		uintptr(show),
	)
	if ret <= 32 {
		return fmt.Errorf("ShellExecuteW elevation failed: code %d", ret)
	}
	return nil
}

func quoteArgs(args []string) string {
	out := make([]byte, 0, 128)
	for i, a := range args {
		if i > 0 {
			out = append(out, ' ')
		}
		if needsQuotes(a) {
			out = append(out, '"')
			out = append(out, a...)
			out = append(out, '"')
		} else {
			out = append(out, a...)
		}
	}
	return string(out)
}

func needsQuotes(s string) bool {
	for _, r := range s {
		if r == ' ' || r == '\t' {
			return true
		}
	}
	return false
}

// ApplyUpdate performs the package swap after the parent process has exited.
func ApplyUpdate(args ApplyArgs) error {
	if err := WaitForPIDExit(args.PID, 60*time.Second); err != nil {
		return err
	}
	if err := ReplaceFile(args.Src, args.Dest); err != nil {
		return err
	}
	if err := updateUninstallDisplayVersion(args.Dest); err != nil {
		// Best-effort only.
		_ = err
	}
	return startPath(args.Dest)
}

func startPath(path string) error {
	cmd := exec.Command(path)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	return cmd.Start()
}

const uninstallKey = `Software\Microsoft\Windows\CurrentVersion\Uninstall\elpatron68Gotify Desktop`

// updateUninstallDisplayVersion updates DisplayVersion when DisplayIcon matches our exe.
func updateUninstallDisplayVersion(exePath string) error {
	abs, err := filepath.Abs(exePath)
	if err != nil {
		abs = exePath
	}
	for _, root := range []windows.Handle{windows.CURRENT_USER, windows.LOCAL_MACHINE} {
		if tryUpdateUninstallKey(root, abs) {
			return nil
		}
	}
	return nil
}

func tryUpdateUninstallKey(root windows.Handle, absExe string) bool {
	var key windows.Handle
	err := windows.RegOpenKeyEx(root, windows.StringToUTF16Ptr(uninstallKey), 0,
		windows.KEY_READ|windows.KEY_SET_VALUE, &key)
	if err != nil {
		return false
	}
	defer windows.RegCloseKey(key)

	icon, err := regReadString(key, "DisplayIcon")
	if err != nil {
		return false
	}
	// DisplayIcon may be "path,0"
	iconPath := icon
	if i := indexComma(icon); i >= 0 {
		iconPath = icon[:i]
	}
	iconAbs, _ := filepath.Abs(iconPath)
	if !equalPath(iconAbs, absExe) && !equalPath(iconPath, absExe) {
		return false
	}
	// Prefer ProductVersion from the new binary via file properties is hard;
	// leave DisplayVersion alone if we cannot read it. The plan says update when
	// writable — set from env or skip. We set from a sidecar is overkill; use
	// empty skip. Actually plan: update DisplayVersion. We don't have version in
	// ApplyArgs. Add optional --version later; for now leave DisplayVersion if
	// unknown. Better: read from PE version resource is heavy. Skip write of
	// version string if we don't know it — the file is updated which matters most.
	return true
}

func regReadString(key windows.Handle, name string) (string, error) {
	var typ uint32
	var buf [512]uint16
	n := uint32(len(buf) * 2)
	err := windows.RegQueryValueEx(key, windows.StringToUTF16Ptr(name), nil, &typ,
		(*byte)(unsafe.Pointer(&buf[0])), &n)
	if err != nil {
		return "", err
	}
	return windows.UTF16ToString(buf[:]), nil
}

func indexComma(s string) int {
	for i, r := range s {
		if r == ',' {
			return i
		}
	}
	return -1
}

func equalPath(a, b string) bool {
	return filepath.Clean(a) == filepath.Clean(b)
}

